INSERT INTO purpose VALUES('kernel-check-memo','','crate','Lets a checker skip a goal it already decided in this process, and gives the kernel its one hash index: the kernel layer''s check-memo seam, inside the validity wall, generic in support and outcome so it names no kernel type.','sharing','fits','unplaced','The lead paragraph names neither the kernel layer nor the validity wall. The # Boundaries hit paragraph repeats CheckMemo''s, the #[non_exhaustive] paragraph restates the workspace rule rather than this crate''s code, and # Witnesses narrates the specification facade''s evaluation order.');
INSERT INTO purpose VALUES('kernel-check-memo','accounting','module','Counts a memo''s entries per plane and in total with checked arithmetic, so a measurement never reads a wrapped count.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','accounting::MemoBucketCount','struct','Counts the distinct digests a memo''s entries are bucketed under; read against the entry count, a smaller number shows a collision.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','accounting::MemoEntryCount','struct','Counts a memo''s entries on one plane or across all, advanced only by a successor that refuses at the ceiling.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','accounting::MemoError','enum','Refuses a recording whose entry count is at its ceiling, the one way a memo fails.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','digest','module','Holds the content digest that picks a memo bucket and the agreement verdict that decides within it.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','digest::ContentAgreement','enum','Says whether two supports have the same content, the verdict a memo serves a hit on.','sharing','fits','inaccurate','Claims a memo implementation that never consults it cannot type check; `NullMemo` never does, and nothing in `CheckMemo` obliges a call to `MemoKey::agreement`.');
INSERT INTO purpose VALUES('kernel-check-memo','digest::ContentDigest','struct','Carries a support''s two-word content digest, which picks a memo bucket and never decides agreement.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','digest::DigestWord','struct','Carries one opaque 64-bit word of a content digest, ordered by its raw value.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','key','module','Holds what a consumer''s support supplies to key a memo.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','key::MemoKey','trait','States what a support supplies to key a memo: its accounting plane, its content digest and the agreement that decides.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','memo','module','Holds the seam and its two memos, the one that never answers and the one that stores.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','memo::CheckMemo','trait','Lets a checker recall an outcome it already computed in this process for an agreeing support and record a new one, its activity known at compile time.','sharing','fits','verbose','Its hit paragraph is repeated in the crate root''s # Boundaries.');
INSERT INTO purpose VALUES('kernel-check-memo','memo::HashedMemo','struct','Stores outcomes by support: files each entry''s position under its support''s content digest, decides among the filed positions by agreement, and counts entries per plane.','sharing','mechanism','verbose','Named for its hash index, a mechanism, rather than for being the memo that stores. Its filed-by-digest paragraph restates `CheckMemo`''s rule that a digest never answers alone, and its unkeyed-hash sentence repeats the `table` module''s.');
INSERT INTO purpose VALUES('kernel-check-memo','memo::MemoActivity','enum','Says at compile time whether a memo ever answers, so the branch around an inactive memo folds away.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','memo::MemoHit','struct','Hands back a recalled outcome borrowed together with the support it was recorded under, for pointwise adoption.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','memo::MemoRecord','enum','Reports what a recording did: stored a fresh entry, replaced an agreeing entry''s outcome, or stored nothing.',NULL,'misleading','sound','Reads as a record the memo holds; it is what `remember` did, which a name such as `Remembered` says.');
INSERT INTO purpose VALUES('kernel-check-memo','memo::NullMemo','struct','Stands for the memoless path as a type parameter: it never answers, never counts, and compiles to the code with no memo.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','overlay','module','Holds the memo a forked job reads its parent''s memo through by reference, and the join that folds the job''s entries back in the order of the jobs and refuses two outcomes under one support.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','overlay::Disagreement','struct','Names the support and the two outcomes that a join met under it, the outcome recorded since the child''s fork and the outcome the child offers, when the two do not glue.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','overlay::OverlaidMemo','struct','Serves a recall from its own entries first and then from each layer frozen at a fork point, newest first, and records into its own entries alone.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','table','module','Holds the kernel''s one hash index, from a key''s hash to dense positions its consumer owns, with the hash, slot, position, probe and filter types it speaks.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','table::Admission','enum','Says whether a filter admits a hash, so a read goes into the filter''s layer, or refuses it, so no key under the hash is filed there.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','table::HashFilter','struct','Filters the hashes one index filed at its build, two bits each in eight per hash, so a frozen memo layer is probed only for a hash it can hold.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','table::HashIndex','struct','Indexes a consumer''s dense vector by key hash, open-addressed and at most half full, leaving every identity decision to the consumer''s comparison.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','table::Probe','enum','Says where a probe for one key ended: at the position of an entry the consumer accepted, or at the vacant slot an insertion would fill.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','table::TableFull','struct','Refuses a position at or past `u32::MAX`, which no slot can record.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','table::TableHash','struct','Carries a key''s 32-bit table hash, an unkeyed fold of its derived `Hash`, so a run files and probes alike on every host.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','table::TablePosition','struct','Names an entry''s dense position in its consumer''s vector, kept below `u32::MAX`, the value that marks a vacant slot.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-check-memo','table::TableSlot','struct','Names the vacant slot a probe ended at, where the insertion that follows files its entry.',NULL,'fits','sound',NULL);
